function HolyStorm.Events:Emit(event,...)self.emitted[#self.emitted+1]={event,...};for _,callback in pairs(self.listeners[event]or{})do callback(event,...)end end
function HolyStorm.Sync:RegisterDomain(id,definition)self.domains[id]=definition;return true end
function HolyStorm.Sync:Publish(domain,id,reason)self.published[#self.published+1]={domain=domain,id=id,reason=reason};return true end
function HolyStorm.Tasks:RegisterTaskType(id,definition)self.types[id]=definition;return true end
