function HolyStorm.DataManager:RegisterSchema(definition)schemas[definition.id]=definition;return{ok=true}end
local function valueAt(root,path)local value=root;for _,key in ipairs(path or{})do value=type(value)=="table"and value[key];if value==nil then return nil end end;return value end
function HolyStorm.DataManager:Get(id,path)return copy(valueAt(roots[id],path))end
function HolyStorm.DataManager:Commit(id,path,value)local schema=assert(schemas[id]);local root=roots[id]or schema.default();roots[id]=root;local parent=root;for index=1,#path-1 do parent[path[index]]=parent[path[index]]or{};parent=parent[path[index]]end;parent[path[#path]]=copy(value);assert(schema.validate(root));return{ok=true,changed=true,value=copy(value)}end
function HolyStorm.DataManager:Transaction(id,path,mutator,context)local current=self:Get(id,path);local replacement=mutator(current,context or{});return self:Commit(id,path,replacement,context)end

